import csv
with open('data/expenses.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        amount = float(row['amount'])
        currency = row['currency']
        if currency == 'GBP':
            gbp = amount
        elif currency == 'EUR':
            gbp = amount * 0.85
        elif currency == 'USD':
            gbp = amount * 0.79
        else:
            continue
        if gbp >= 500:
            print(f'{row[\"id\"]}: {amount} {currency} -> {gbp:.2f} GBP')
